def run():
    data = input().split()
    n = int(data[0])
    m = int(data[1])
    if n > m:
        n, m = m, n

    def bruteforce(n, m):
        even_points = []
        odd_points = []
        for i in range(n):
            for j in range(m):
                if (i + j) % 2 == 0:
                    even_points.append((i, j))
                else:
                    odd_points.append((i, j))
        adj = [[False] * len(odd_points) for _ in range(len(even_points))]
        for i in range(len(even_points)):
            for j in range(len(odd_points)):
                dist = abs(even_points[i][0] - odd_points[j][0]) + abs(even_points[i][1] - odd_points[j][1])
                if dist == 3:
                    adj[i][j] = True
        return 2 * max_matching(adj)

    def max_matching(g):
        n1 = len(g)
        n2 = len(g[0]) if n1 > 0 else 0
        match = [-1] * n2

        def dfs(u, visited):
            for v in range(n2):
                if g[u][v] and not visited[v]:
                    visited[v] = True
                    if match[v] == -1 or dfs(match[v], visited):
                        match[v] = u
                        return True
            return False

        count = 0
        for u in range(n1):
            visited = [False] * n2
            if dfs(u, visited):
                count += 1
        return count

    if n == 1:
        m -= 1
        pattern = [0, 0, 0, 2, 4, 6]
        res = (m // 6) * 6 + pattern[m % 6]
        print(res)
        return
    elif n == 2:
